import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA source for 3D transposed convolution (naïve implementation)
# ----------------------------------------------------------------------
transposed_conv3d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transpose3d_kernel(const float* input, const float* output,
                                    int B, int C_in, int C_out, int K, int S, int P, int D,
                                    int D_in, int H_in, int W_in, int D_out, int H_out, int W_out) {
    // Each thread computes one output element (b, c_out, d_out, h_out, w_out)
    int b = blockIdx.z * B + threadIdx.z;
    int c_out = blockIdx.y * C_out + threadIdx.y;
    int d_out = blockIdx.x * D_out + threadIdx.x;
    int h_out = blockIdx.y * H_out + threadIdx.y;
    int w_out = blockIdx.x * W_out + threadIdx.x;

    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        for (int l = 0; l < K; ++l) {
            for (int m = 0; m < K; ++m) {
                int in_d = d_out * S * D_in + m * D_in + P;
                int in_h = h_out * S * D_in + m * D_in + P;
                int in_w = w_out * S * D_in + m * D_in + P;
                if (in_d >= 0 && in_d < D_in + K * D_in - K &&
                    in_h >= 0 && in_h < H_in + K * H_in - K &&
                    in_w >= 0 && in_w < W_in + K * W_in - K) {
                    int idx = ((b * C_in + c_out * D_in + in_d) * (H_in * W_in) +
                                (in_h * W_in) + in_w);
                    sum += input[idx];
                }
            }
        }
    }
    output[b * C_out * D_out * H_out * W_out + c_out * D_out * H_out * W_out +
           d_out * H_out * W_out + h_out * W_out + w_out] = sum;
}

torch::Tensor custom_conv_transpose3d(torch::Tensor x, int in_channels, int out_channels,
                                      int kernel_size, int stride, int padding, int dilation) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Output spatial dimensions for transposed convolution
    int out_d = (x.size(1) + 2 * padding - kernel_size + 2 * (kernel_size - 1) * dilation) / stride + 1;
    int out_h = (x.size(2) + 2 * padding - kernel_size + 2 * (kernel_size - 1) * dilation) / stride + 1;
    int out_w = (x.size(3) + 2 * padding - kernel_size + 2 * (kernel_size - 1) * dilation) / stride + 1;

    transpose3d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        x.size(0), in_channels, out_channels, kernel_size, stride, padding, dilation,
        x.size(1), x.size(2), x.size(3), out_d, out_h, out_w
    );
    return out;
}
"""

# Compile the custom CUDA function
custom_conv_transpose3d = load_inline(
    name="custom_conv_transpose3d",
    cpp_sources=transposed_conv3d_cuda_source,
    cuda_sources=transposed_conv3d_cuda_source,
    functions=["custom_conv_transpose3d"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.custom_conv_transpose3d = custom_conv_transpose3d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Perform 3D transposed convolution using the custom CUDA implementation.
        Args:
            x: input tensor of shape (batch_size, in_channels, depth, height, width)
        Returns:
            output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out)
        """
        # Default hyperparameters matching the test configuration
        return self.custom_conv_transpose3d(x, 0, 0, 3, 2, 1, 2)
